'use strict';
function noteReminderActive(n){return !!n.remindAt&&!(n.type==='todo'&&n.items?.length&&n.items.every(i=>i.done));}
function noteReminderKey(n){return n.id+'|'+n.remindAt+'|'+(n.remindBefore??60);}
function dueNoteReminders(){return (data.notes||[]).filter(n=>noteReminderActive(n)&&Date.parse(n.remindAt+'+07:00')-(n.remindBefore??60)*60000<=Date.now());}
function noteExtraValues(form,n){const fd=new FormData(form),kind=fd.get('note-kind')||'note',keywords=[...new Set(String(fd.get('note-keywords')||'').split(',').map(s=>s.trim()).filter(Boolean))];if(keywords.length>20||keywords.some(s=>s.length>40)){notify('Tối đa 20 từ khóa, mỗi từ khóa tối đa 40 ký tự.');return false;}const remindAt=fd.has('note-remind-enabled')?String(fd.get('note-remind-at')||''):'';if(fd.has('note-remind-enabled')&&!remindAt){notify('Chọn ngày và giờ nhắc ghi chú.');return false;}if(remindAt&&remindAt!==n?.remindAt&&Date.parse(remindAt+'+07:00')<=Date.now()){notify('Thời gian nhắc cần ở tương lai.');return false;}const items=[];form.querySelectorAll('[data-note-item-text]').forEach(input=>{if(input.closest('.note-item-row').querySelector('[data-note-item-remove]').checked)return;const text=input.value.trim();if(text)items.push({text,done:input.closest('.note-item-row').querySelector('[data-note-item-done]').checked});});for(const text of String(fd.get('note-extra-items')||'').split('\n').map(s=>s.trim()).filter(Boolean))items.push({text,done:false});if(items.length>200||items.some(i=>i.text.length>300)){notify('Tối đa 200 mục checklist, mỗi mục tối đa 300 ký tự.');return false;}return {type:kind==='note'&&n?.type&&n.type!=='todo'?n.type:kind,items,keywords,remindAt,remindBefore:Number(fd.get('note-remind-before')||60),remindEmail:!!remindAt&&fd.has('note-remind-email')};}
const keepFormBeforePlus=noteForm;noteForm=function(n){if(contentReadOnly)return;keepFormBeforePlus(n);const composer=$('.note-composer'),kind=n?.type==='todo'?'todo':'note';composer.insertAdjacentHTML('afterbegin','<label class="note-type-field">Nội dung<select name="note-kind"><option value="note" '+(kind==='note'?'selected':'')+'>Ghi chú</option><option value="todo" '+(kind==='todo'?'selected':'')+'>Checklist</option></select></label>');composer.querySelector('textarea[name=text]').insertAdjacentHTML('afterend','<section class="note-check-editor" '+(kind==='todo'?'':'hidden')+'><h3>Các bước cần làm</h3>'+(n?.items||[]).map((item,i)=>'<div class="note-item-row"><input type="checkbox" data-note-item-done '+(item.done?'checked':'')+' aria-label="Hoàn thành mục '+(i+1)+'"><textarea rows="1" data-note-item-text maxlength="300" aria-label="Nội dung mục '+(i+1)+'">'+esc(item.text)+'</textarea><input type="checkbox" data-note-item-remove hidden><button type="button" data-note-item-hide aria-label="Bỏ mục '+(i+1)+'">×</button></div>').join('')+'<label>Thêm mục (mỗi dòng một mục)<textarea name="note-extra-items" maxlength="20000" placeholder="Một bước nhỏ đầu tiên…"></textarea></label></section>');composer.querySelector('textarea[name=text]').hidden=kind==='todo';composer.querySelector('[name=note-kind]').onchange=e=>{composer.querySelector('.note-check-editor').hidden=e.target.value!=='todo';composer.querySelector('textarea[name=text]').hidden=e.target.value==='todo';};composer.querySelector('.note-toolbar').insertAdjacentHTML('beforebegin','<label class="note-keywords-field">Từ khóa<input name="note-keywords" maxlength="820" placeholder="Ý tưởng, Công việc, Gia đình…" value="'+esc((n?.keywords||[]).join(', '))+'"><small>Phân cách bằng dấu phẩy · Bấm nhãn trên thẻ để lọc.</small></label><details class="note-reminder-options" '+(n?.remindAt?'open':'')+'><summary>'+svgIcon('bell')+'Nhắc tôi</summary><label class="settings-toggle"><input type="checkbox" name="note-remind-enabled" '+(n?.remindAt?'checked':'')+'> Bật lịch nhắc cho ghi chú</label><label>Ngày và giờ (Việt Nam)<input type="hidden" name="note-remind-at" value="'+esc(n?.remindAt||'')+'"><button type="button" class="date-field-trigger" id="note-time-trigger">'+esc(n?.remindAt?.replace('T',' · ')||'Chọn ngày và giờ')+'</button></label><label>Nhắc trước<select name="note-remind-before">'+[[15,'15 phút'],[60,'1 giờ'],[1440,'1 ngày']].map(([v,t])=>'<option value="'+v+'" '+((n?.remindBefore??60)===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="settings-toggle"><input type="checkbox" name="note-remind-email" '+(n?.remindEmail!==false?'checked':'')+'> Gửi email nhắc ghi chú này</label><small>Hệ thống kiểm tra mỗi 5 phút. Bỏ chọn bật lịch nhắc hoặc hoàn tất checklist để ngừng nhắc.</small></details>');const input=composer.querySelector('[name=note-remind-at]'),trigger=$('#note-time-trigger');trigger.onclick=()=>{composer.querySelector('[name=note-remind-enabled]').checked=true;showTimePicker(input,true,trigger);};composer.querySelectorAll('.note-item-row textarea').forEach(fitCheckText);};
let noteKeywordFilter='';
function noteMatches(n){const hay=[n.title,n.text,n.group,...(n.keywords||[]),...(n.items||[]).map(i=>i.text)].join(' ').toLocaleLowerCase('vi');return hay.includes(query.toLocaleLowerCase('vi'))&&(!noteKeywordFilter||(n.keywords||[]).includes(noteKeywordFilter));}
notesPage=function(){const notes=(data.notes||[]).filter(noteMatches),keywords=[...new Set((data.notes||[]).flatMap(n=>n.keywords||[]))].sort((a,b)=>a.localeCompare(b,'vi'));return heading('KHÔNG GIAN Ý TƯỞNG','Ghi chú','Ghi nhanh, checklist và lời nhắc trong cùng một nơi.',contentReadOnly?'':'<button class="btn primary" data-note-new>+ Ghi chú mới</button>')+'<div class="note-label-filters"><button class="note-keyword '+(!noteKeywordFilter?'selected':'')+'" data-note-keyword="">Tất cả</button>'+keywords.map(k=>'<button class="note-keyword '+(noteKeywordFilter===k?'selected':'')+'" data-note-keyword="'+esc(k)+'">'+esc(k)+'</button>').join('')+'</div><div class="keep-grid">'+notes.map(n=>'<article tabindex="0" role="button" class="keep-card" style="--card-color:'+n.color+'"><small>'+esc(n.group||'Ghi chú')+'</small><h3>'+esc(n.title)+'</h3>'+(n.type==='todo'&&n.text?'<p>'+esc(n.text).replace(/\n/g,'<br>')+'</p>':'')+(contentReadOnly?noteContent(n).replace(/type="checkbox"/g,'type="checkbox" disabled'):noteContent(n))+(n.type==='todo'&&n.url?'<a href="'+esc(n.url)+'" target="_blank" rel="noopener noreferrer">Mở liên kết ↗</a>':'')+'<div class="note-keywords">'+(n.keywords||[]).map(k=>'<button type="button" class="note-keyword" data-note-keyword="'+esc(k)+'">'+esc(k)+'</button>').join('')+'</div>'+(n.remindAt?'<button type="button" class="note-remind-chip" data-open-note="'+esc(n.id)+'">'+svgIcon('bell')+esc(n.remindAt.replace('T',' · '))+(noteReminderActive(n)?'':' · Đã xong')+'</button>':'')+(contentReadOnly?'':'<div class="keep-actions"><button class="btn" data-note-edit="'+esc(n.id)+'" aria-label="Sửa ghi chú '+esc(n.title)+'">'+svgIcon('edit')+'Sửa</button><button class="btn" data-note-files="'+esc(n.id)+'">'+svgIcon('attach')+'Tệp</button><button class="btn" data-note-delete="'+esc(n.id)+'" aria-label="Xóa ghi chú '+esc(n.title)+'">'+svgIcon('trash')+'</button></div>')+'</article>').join('')+(!notes.length?'<p class="empty">Chưa có ghi chú phù hợp.</p>':'')+'</div>';};
document.addEventListener('click',e=>{const label=e.target.closest('[data-note-keyword]'),hide=e.target.closest('[data-note-item-hide]'),open=e.target.closest('[data-open-note]');if(label){noteKeywordFilter=label.dataset.noteKeyword;view='notes';render();}if(hide){const row=hide.closest('.note-item-row');row.querySelector('[data-note-item-remove]').checked=true;row.hidden=true;}if(open){const n=data.notes?.find(n=>n.id===open.dataset.openNote);if(n){localWrite('zen-note-seen:'+currentUser?.id+':'+noteReminderKey(n),'1');noteForm(n);refreshBell();}}});
// Avoid whole-card keyboard/click handling for native checklist controls.
document.addEventListener('click',e=>{if(e.target.closest('[data-card-check],.card-check-control,[data-note-check],.keep-card .check-row'))e.stopImmediatePropagation();},true);
document.addEventListener('keydown',e=>{if(e.target.closest('[data-card-check],[data-note-check]'))e.stopImmediatePropagation();},true);
const noteBellBefore=refreshBell;refreshBell=function(){noteBellBefore();const notes=dueNoteReminders().filter(n=>!localRead('zen-note-seen:'+currentUser?.id+':'+noteReminderKey(n)));if(!currentUser||!notes.length)return;const base=Number(bell.querySelector('.notification-count')?.textContent.replace('+','')||0),count=base+notes.length;bell.innerHTML=svgIcon('bell')+'<span class="notification-count">'+(count>99?'99+':count)+'</span>';bell.setAttribute('aria-label','Thông báo · '+count+' chưa xem');};
const noteBellClickBefore=bell.onclick;bell.onclick=()=>{noteBellClickBefore();$('#editor-body .notice-list').insertAdjacentHTML('afterbegin',dueNoteReminders().map(n=>'<button type="button" class="notice-item" data-open-note="'+esc(n.id)+'"><strong>'+svgIcon('bell')+' Nhắc ghi chú</strong><span>'+esc(n.title)+'</span><small>'+esc(n.remindAt.replace('T',' · '))+' · Giờ Việt Nam</small><span class="notice-detail-link">Xem chi tiết →</span></button>').join(''));const all=$('#clear-file-alerts');if(all){const prior=all.onclick;all.onclick=()=>{dueNoteReminders().forEach(n=>localWrite('zen-note-seen:'+currentUser?.id+':'+noteReminderKey(n),'1'));prior?.();refreshBell();};}};
const renderBeforeNotesPlus=render;render=function(){renderBeforeNotesPlus();if(view==='dashboard'){const notes=(data.notes||[]).filter(noteReminderActive).sort((a,b)=>a.remindAt.localeCompare(b.remindAt));if(notes.length)$('#main').insertAdjacentHTML('afterbegin','<section class="note-due-banner"><strong>'+svgIcon('bell')+notes.length+' ghi chú đã đặt lịch</strong><div>'+notes.slice(0,4).map(n=>'<button type="button" data-open-note="'+esc(n.id)+'">'+esc(n.title)+' · '+esc(n.remindAt.replace('T',' '))+'</button>').join('')+(notes.length>4?'<button type="button" data-note-reminders-all>Xem tất cả '+notes.length+' ghi chú</button>':'')+'</div></section>');}refreshBell();};
setInterval(()=>{if(currentUser&&!document.hidden){refreshBell();if(view==='dashboard'&&!$('#editor').open)render();}},60000);

document.addEventListener('click',e=>{if(!e.target.closest('[data-note-reminders-all]'))return;modal('<h2>Ghi chú đã đặt lịch</h2><div class="notice-list">'+(data.notes||[]).filter(noteReminderActive).sort((a,b)=>a.remindAt.localeCompare(b.remindAt)).map(n=>'<button type="button" class="notice-item" data-open-note="'+esc(n.id)+'"><strong>'+esc(n.title)+'</strong><small>'+esc(n.remindAt.replace('T',' · '))+' · Giờ Việt Nam</small></button>').join('')+'</div>',null,true);});
